settings.customCss:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap');
.mfp.mfp-nlt.mfp-native-generated {--nlt-primary:#EAB308;--nlt-accent:#F97316;--nlt-surface:var(--mf-page-surface,var(--mf-preset-surface,#FFFFFF));--nlt-text:var(--mf-page-text,var(--mf-preset-text,#080C0F));--nlt-muted:var(--mf-page-muted,var(--mf-preset-muted,#5E6468));--nlt-border:var(--mf-page-border,var(--mf-preset-border,#D2D8DD));--nlt-on-primary:var(--mf-preset-on-primary,#FCFCFC);--nlt-deco:#F97316;--nlt-page:#FFFBEB;--nlt-fill:#FFFBEB;--nlt-fill-strong:color-mix(in srgb, var(--nlt-text) 9%, var(--nlt-surface));--nlt-soft:color-mix(in srgb, var(--nlt-primary) 12%, var(--nlt-surface));--nlt-hairline:color-mix(in srgb, var(--nlt-text) 12%, var(--nlt-surface));}.mfp.mfp-nlt.mfp-native-generated {background:transparent!important;border:0!important;padding:0!important;font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif}.mfp.mfp-nlt.mfp-native-generated {--nlt-primary:var(--mf-page-primary,var(--mf-preset-primary,#EAB308));--nlt-accent:var(--mf-page-accent,var(--mf-preset-accent,#F97316));--nlt-surface:var(--mf-page-surface,var(--mf-preset-surface,#FFFFFF));--nlt-text:var(--mf-page-text,var(--mf-preset-text,#080C0F));--nlt-border:var(--mf-page-border,var(--mf-preset-border,#D2D8DD));--nlt-on-primary:var(--mf-page-on-primary,var(--mf-preset-on-primary,#FCFCFC));--nlt-page:var(--mf-preset-bg,#FFFBEB);}@container (max-width:520px){.mfp.mfp-nlt.mfp-native-generated [class*="-grid"],.mfp.mfp-nlt.mfp-native-generated [class*="-meta"],.mfp.mfp-nlt.mfp-native-generated [class*="-scores"],.mfp.mfp-nlt.mfp-native-generated [class*="-charts"],.mfp.mfp-nlt.mfp-native-generated [class*="-cols"]{grid-template-columns:1fr!important}.mfp.mfp-nlt.mfp-native-generated [class*="-body"],.mfp.mfp-nlt.mfp-native-generated [class*="-split"],.mfp.mfp-nlt.mfp-native-generated [class*="-foot"],.mfp.mfp-nlt.mfp-native-generated [class*="-head"],.mfp.mfp-nlt.mfp-native-generated [class*="-row"]{flex-wrap:wrap!important}.mfp.mfp-nlt.mfp-native-generated [class*="-aside"],.mfp.mfp-nlt.mfp-native-generated [class*="-side"]{flex:1 1 100%!important;width:100%!important;max-width:none!important}}.mfp.mfp-nlt.mfp-native-generated  img{max-width:100%!important;height:auto}.mfp.mfp-nlt.mfp-native-generated {overflow-wrap:break-word}

/* The wrapper itself: strip the host's card, but NOT its width. Layout > Max width in the module
   settings (480/640/768/960/Full) is a max-width on THIS element, and the previous version of this
   rule overrode it with max-width:none!important - so picking 960 did nothing at all. */
.mf-form-wrapper:has(.mfp-nlt){background:transparent!important;border:0!important;
  border-radius:0!important;box-shadow:none!important;padding:0!important}
/* The boxes INSIDE it have their own measures, and those are what squeezed the design. */
.mf-form-wrapper:has(.mfp-nlt) > .mf-form-inner,
.mf-form-wrapper:has(.mfp-nlt) .mf-form,
.mf-form-wrapper:has(.mfp-nlt) .mf-fields-container{background:transparent!important;
  border:0!important;border-radius:0!important;box-shadow:none!important;padding:0!important;
  margin:0!important;max-width:none!important;width:100%!important}

.mfp.mfp-nlt.mfp-native-generated {font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif!important;color:var(--nlt-text)}
.mfp.mfp-nlt.mfp-native-generated .nlt-page{padding:64px 0;background:linear-gradient(to bottom right,var(--nlt-page) 0%,#FFF7ED 100%)}
.mfp.mfp-nlt.mfp-native-generated .nlt-shell{max-width:448px;margin:0 auto;padding:0 16px}
.mfp.mfp-nlt.mfp-native-generated .nlt-back{line-height:0}
/* mb-6 sits on the LINK in the mock, not on a wrapper. */
.mfp.mfp-nlt.mfp-native-generated .nlt-back-link{display:inline-flex;align-items:center;margin-bottom:24px;font-size:14px;
  line-height:20px;font-weight:400;color:#5E6468}
.mfp.mfp-nlt.mfp-native-generated .nlt-back-link i{margin-right:4px;font-size:14px;line-height:16px}
.mfp.mfp-nlt.mfp-native-generated .nlt-card{display:flex;flex-direction:column;gap:24px;padding:24px 0;border:1px solid var(--nlt-border);
  border-radius:12px;background:#fff;box-shadow:0 1px 2px 0 rgba(0,0,0,.05)}
/* CardHeader is a grid with gap-2; the description carries no margin of its own. */
.mfp.mfp-nlt.mfp-native-generated .nlt-head{display:grid;gap:8px;padding:0 24px;text-align:center}
.mfp.mfp-nlt.mfp-native-generated .nlt-tile{display:flex;align-items:center;justify-content:center;width:48px;height:48px;
  margin:0 auto 16px;border-radius:8px;color:#fff;font-size:24px;line-height:24px;
  background:linear-gradient(to right,var(--nlt-primary) 0%,var(--nlt-accent) 100%)}
.mfp.mfp-nlt.mfp-native-generated .nlt-head-h{font-size:24px;line-height:32px;font-weight:600;color:var(--nlt-text)}
.mfp.mfp-nlt.mfp-native-generated .nlt-head-d{margin:0;font-size:14px;line-height:20px;font-weight:400;color:#5E6468}
.mfp.mfp-nlt.mfp-native-generated .nlt-body{display:flex;flex-direction:column;gap:20px;padding:0 24px}
.mfp.mfp-nlt.mfp-native-generated .nlt-field{display:block;margin:0}
/* shadcn's Label is flex/items-center/gap-2 - the gap is measurable even with one child. */
.mfp.mfp-nlt.mfp-native-generated .nlt-label{display:flex;align-items:center;gap:8px;margin:0 0 8px;font-size:14px;
  line-height:14px;font-weight:500;color:var(--nlt-text)}
.mfp.mfp-nlt.mfp-native-generated .nlt-freq .nlt-label{margin-bottom:12px}

/* megaform sets font-family on label/input/select/textarea with !important, so an authored
   <span> inside a <label> inherits the HOST typeface no matter what the shell root declares.
   Element selectors are (0,3,1) here - above megaform, below every authored class rule - and
   <i> is left alone so Font Awesome keeps its own family. */
.mfp.mfp-nlt.mfp-native-generated label,.mfp.mfp-nlt.mfp-native-generated span,.mfp.mfp-nlt.mfp-native-generated p,.mfp.mfp-nlt.mfp-native-generated div,.mfp.mfp-nlt.mfp-native-generated ul,.mfp.mfp-nlt.mfp-native-generated li,.mfp.mfp-nlt.mfp-native-generated h1,.mfp.mfp-nlt.mfp-native-generated h2,.mfp.mfp-nlt.mfp-native-generated h3,.mfp.mfp-nlt.mfp-native-generated button{font-family:inherit!important}
.mfp.mfp-nlt.mfp-native-generated .mf-field-label{display:none!important}
/* A wizard's page-break Section renders a visible heading the mock has no room for - it exists to
   split the pages, not to be seen. */
.mfp.mfp-nlt.mfp-native-generated .mf-section-break,.mfp.mfp-nlt.mfp-native-generated .mf-section-title{display:none!important}
.mfp.mfp-nlt.mfp-native-generated .mf-field-group{margin:0!important;width:100%}
.mfp.mfp-nlt.mfp-native-generated .mf-form-title,.mfp.mfp-nlt.mfp-native-generated .mf-form-description,.mfp.mfp-nlt.mfp-native-generated .mf-form-actions{display:none!important}
.mfp.mfp-nlt.mfp-native-generated .mf-option-item{margin:0!important}
/* megaform gives every option chip a 36px floor and paints .mf-option-icon as a rounded tile. */
.mfp.mfp-nlt.mfp-native-generated .mf-option-group--chips .mf-option-check,
.mfp.mfp-nlt.mfp-native-generated .mf-option-group--cards .mf-option-check{display:none!important}
.mfp.mfp-nlt.mfp-native-generated .mf-option-group--chips .mf-option-ui{min-height:0!important;height:auto!important}
.mfp.mfp-nlt.mfp-native-generated .mf-option-group--cards .mf-option-copy{display:block;width:100%}

.mfp.mfp-nlt.mfp-native-generated .mf-input[class]{width:100%!important;box-sizing:border-box!important;
  border:1px solid var(--nlt-border)!important;border-radius:6px!important;background:transparent!important;
  padding:4px 12px!important;min-height:0!important;height:36px!important;color:var(--nlt-text)!important;
  font-family:inherit!important;font-size:14px!important;line-height:20px!important;
  font-weight:400!important;box-shadow:0 1px 2px 0 rgba(0,0,0,.05)!important}
.mfp.mfp-nlt.mfp-native-generated .mf-select[class]{width:100%!important;box-sizing:border-box!important;
  border:1px solid var(--nlt-border)!important;border-radius:6px!important;
  background:rgb(247,249,250)!important;padding:0 12px!important;min-height:0!important;
  height:40px!important;color:var(--nlt-text)!important;font-family:inherit!important;
  font-size:14px!important;line-height:20px!important;font-weight:400!important;
  box-shadow:none!important;appearance:none!important;-webkit-appearance:none!important}
.mfp.mfp-nlt.mfp-native-generated .mf-input[class]::placeholder{color:#5E6468!important;opacity:1}
.mfp.mfp-nlt.mfp-native-generated .mf-input[class]:focus,.mfp.mfp-nlt.mfp-native-generated .mf-select[class]:focus{border-color:var(--nlt-border)!important;
  box-shadow:none!important;outline:none!important}
/* Two real checkboxes on ONE row, 16px apart - the mock has no chips here. */
.mfp.mfp-nlt.mfp-native-generated .nlt-freq .mf-option-group{display:flex!important;flex-direction:row!important;gap:16px!important;
  flex-wrap:nowrap!important}
.mfp.mfp-nlt.mfp-native-generated .nlt-freq .mf-option-item{margin:0!important}
.mfp.mfp-nlt.mfp-native-generated .nlt-freq .mf-option-ui{display:flex;align-items:center;gap:8px;padding:0;border:0;
  background:transparent}
.mfp.mfp-nlt.mfp-native-generated .nlt-freq .mf-option-label{display:flex;align-items:center;gap:8px;font-size:14px;
  line-height:14px;font-weight:400;color:var(--nlt-text)}
.mfp.mfp-nlt.mfp-native-generated .nlt-freq input[type="checkbox"]{width:16px!important;height:16px!important;margin:0!important;
  flex:0 0 16px!important;border:1px solid var(--nlt-border)!important;border-radius:4px!important}
.mfp.mfp-nlt.mfp-native-generated button.nlt-submit[type="submit"]{display:flex;align-items:center;justify-content:center;gap:8px;
  width:100%!important;height:36px!important;padding:8px 16px!important;border:0!important;
  border-radius:6px!important;
  background:linear-gradient(to right,var(--nlt-primary) 0%,var(--nlt-accent) 100%)!important;color:var(--nlt-on-primary)!important;
  font-family:inherit!important;font-size:14px!important;line-height:20px!important;
  font-weight:500!important;letter-spacing:normal!important;text-transform:none!important;
  cursor:pointer!important;box-shadow:none!important}
/* The mock's button is never gated. */
.mfp.mfp-nlt.mfp-native-generated button.nlt-submit.mf-nav-blocked,.mfp.mfp-nlt.mfp-native-generated button.nlt-submit[disabled]{opacity:1;
  background:linear-gradient(to right,var(--nlt-primary) 0%,var(--nlt-accent) 100%)!important;filter:none!important}
.mfp.mfp-nlt.mfp-native-generated .nlt-page{padding:0!important;background:transparent!important;min-height:0!important}.mfp.mfp-nlt.mfp-native-generated .nlt-shell,.mfp.mfp-nlt.mfp-native-generated .nlt-wrap{max-width:none!important;margin:0!important}.mfp.mfp-nlt.mfp-native-generated .nlt-grid,.mfp.mfp-nlt.mfp-native-generated .nlt-main,.mfp.mfp-nlt.mfp-native-generated .nlt-hero-in,.mfp.mfp-nlt.mfp-native-generated .nlt-card{max-width:none!important;margin-left:0!important;margin-right:0!important}
